from pathlib import Path
import json
ROOT=Path(__file__).parent
r=json.loads((ROOT/'results.json').read_text());b=json.loads((ROOT/'baseline.json').read_text());s=r['summary'];names=['independent_mean','moderate_mean','strong_mean','strong_contrast'];titles={'independent_mean':'独立・平均で分類','moderate_mean':'相関0.5・平均で分類','strong_mean':'相関0.9・平均で分類','strong_contrast':'相関0.9・差で分類'}
assert len(r['runs'])==20,'Report must use all 20 completed paired runs.'
lines=['# 特徴間の依存を強めた比較実験','','「元のデータの特徴が独立だから、列置換とコピュラ置換の差が小さいのではないか」を調べるため、既存データの相関を確認し、依存の強さを制御した合成データで追加比較した。実験条件は結果を見る前に固定した。','','## 既存データは独立だったか','','|データ|特徴ペアの平均絶対Pearson相関|最大絶対相関|絶対相関0.7超のペア|','|---|---:|---:|---:|']
for name,title in [('breast_cancer','Breast Cancer'),('wine','Wine')]:
 d=r['existing_data_dependence'][name];lines.append(f"|{title}|{d['mean_abs_pearson']:.3f}|{d['max_abs_pearson']:.3f}|{d['fraction_abs_pearson_gt_0_7']*100:.1f}%|")
lines+=['','Breast Cancerの平均半径と平均周長はr=0.998、Wineの総フェノール量とフラバノイドはr=0.865。したがって、特徴がすべて独立という説明は成り立たない。相関が低いペアについて独立と結論したわけではない。相関を持たない非線形依存もある。ここではデータ全体の記述統計を確認しただけで、テストデータから分類器やコピュラを学習していない。','','## 追加データと問題設定','','各反復で1000行・12個の連続特徴を新たに生成した。共通因子Sと各列の雑音ε_jを独立な標準正規とし、次の式を使った。','','```text','X_j = sqrt(ρ) S + sqrt(1−ρ) ε_j','ρ ∈ {0, 0.5, 0.9}','```','','理論上、各列は同じ標準正規分布で、異なる列の相関はρになる。ρ=0だけが独立の対照。相関0.9ではすべての特徴ペアが強く関係する。周辺分布、行数、列数を変えずに依存を変えた。','','分類課題は次の二つ。','','```text','平均の課題：T = sum(X_j) / sqrt(12 × (1 + 11ρ))','差の課題：  T = (X_1 − X_2) / sqrt(2 × (1−ρ))','ラベル：    y = 1[T + 0.35η > 0]、ηは独立な標準正規','```','','平均の課題は全ρで実施。差の課題はρ=0.9で実施した。どちらもTの理論分散を1にし、同じラベル雑音を加えた。平均の課題では共通の傾向が分類に役立つ。差の課題では強く似た特徴の小さな違いが分類に役立つ。後者も、線形な境界で分類可能な問題である。','','## 共通の学習条件','','各条件5反復、seed=11,23,37,51,67。反復ごとに新しい合成標本を生成し、その標本を2手法で共有した。訓練80%・テスト20%で層化分割し、訓練内ラベルあり30%（240行）、ラベルなし560行、テスト200行。MinMaxは訓練だけでfit、コピュラはラベルなし訓練だけでfitした。','','既存のPyTorch VIME再実装で置換器だけを変更した。4層×幅32、自己教師あり15 epoch、半教師あり300反復、batch64、置換確率0.4、一貫性3view・重み1、復元重み2、CPU・1thread。前回の比較と同じ学習設定であり、VIME原論文の全実験の再現ではない。全学習中のマスクが完全一致する保証はない。置換器によって乱数の消費が異なる。','','## 分類結果','','ROC-AUCの平均 ± 標準偏差。差はコピュラから列置換を引いた値。','','|データと課題|列置換|コピュラ置換|平均差|差の探索的95%区間|','|---|---:|---:|---:|---|']
for name in names:
 v=s[name];a=v['column_shuffle']['auc'];c=v['gaussian_copula']['auc'];d=v['paired_auc_difference'];lo,hi=d['ci95'];lines.append(f"|{titles[name]}|{a['mean']:.3f} ± {a['std']:.3f}|{c['mean']:.3f} ± {c['std']:.3f}|{d['mean']:+.3f}|[{lo:+.3f}, {hi:+.3f}]|")
lines+=['','区間は5組の対応したAUC差をpercentile bootstrapしたもの（1万回）。少数の反復による探索的な区間で、複数条件の検討も含むため確証的な有意差検定として扱わない。seed別値とAccuracy・Balanced accuracy・Macro-F1はresults.jsonとper_seed_metrics.csvに保存した。','','## 置換後の関係と、分類の意味は保たれたか','','同じテスト行に同じ確率0.4のマスクを適用し、生成器の診断だけを行った。コピュラはラベルなし訓練で推定済み。列置換は評価行内で各列を並べ替えた。この評価用生成行を分類器の学習やハイパーパラメータ選択に使っていない。残した列が完全に一致することも確認した。','','|課題|元の平均絶対相関|列置換後|コピュラ置換後|列置換の境界変更率|コピュラの境界変更率|','|---|---:|---:|---:|---:|---:|']
for name in names:
 q=s[name]['quality_mean'];lines.append(f"|{titles[name]}|{q['original']['mean_abs_pearson']:.3f}|{q['column_shuffle']['mean_abs_pearson']:.3f}|{q['gaussian_copula']['mean_abs_pearson']:.3f}|{q['column_shuffle']['oracle_boundary_flip_rate']*100:.1f}%|{q['gaussian_copula']['oracle_boundary_flip_rate']*100:.1f}%|")
lines+=['','境界変更率は、ラベル雑音を加える前の既知の規則T>0が、置換で逆転した行の割合である。現実のデータで未知の正解ラベルを完全評価したという意味ではない。元のラベルyには雑音も含まれるため、yそのものの変更率とも異なる。','','真の条件平均からの残差二乗を真の条件分散で割った指標も記録した。正しい条件付き生成なら期待値は1で、0が良い指標ではない（条件平均へ固定すると多様性を失う）。これは条件付き分布の完全な適合検定ではない。','','|課題|元データ|列置換|コピュラ置換|','|---|---:|---:|---:|']
for name in names:
 q=s[name]['quality_mean'];lines.append(f"|{titles[name]}|{q['original']['conditional_residual_ratio']:.3f}|{q['column_shuffle']['conditional_residual_ratio']:.3f}|{q['gaussian_copula']['conditional_residual_ratio']:.3f}|")
lines+=['','## 学習設定の診断','','同じラベルあり240行だけを使うロジスティック回帰も確認した。StandardScalerとC=10を事前に固定。モデル・目的関数が違うため、コピュラの効果を測る直接対照には使わず、分類課題が学習可能かの確認に使う。','','|課題|ラベルありのみのロジスティック回帰AUC|','|---|---:|']
for name in names:
 a=b['summary'][name]['logistic_auc'];lines.append(f"|{titles[name]}|{a['mean']:.3f} ± {a['std']:.3f}|")
lines+=['','一部のVIME結果が低い場合、特徴が独立だからという説明だけでは不十分である。今回の再実装では前学習後のエンコーダを固定し、分類器を学習する。表現が分類に必要な情報を残すか、前学習の予算、一貫性制約の影響も検討が必要。これらが原因であることを今回の結果だけで特定したわけではない。','','## 研究への示唆','','「関係があるか」「生成がその関係を保つか」「分類に必要な情報を保つか」「学習に役立つか」を別々に評価する必要がある。強い相関を持つデータで優位性が保証されるわけではない。また、今回の合成分布はGaussian copulaの仮定に合うため、他の依存形や実社会のデータへの有効性は別に検証する。','','次の候補は、近傍から行をまとめて採る方法との比較、ラベルなしの学習表現の確認、マスク率と一貫性重みを検証用分割だけで選ぶ比較である。テスト結果を見ながら有利な条件だけを選ばない。','','## 再実行と記録','','run_dependence_comparison.pyが主実験、check_baseline.pyが線形診断、plot_results.pyが図の作成、write_report.pyが集計。実行環境と全反復の値はresults.jsonに保存。依存ライブラリはrequirements.txtに記録。元の分類器と置換器の実装は変更していない。',f"\n主実験の実行時間：{r['elapsed_sec']:.1f}秒。"]
diagnosis=json.loads((ROOT/'seed37_diagnosis.json').read_text())
q=diagnosis['results']['gaussian_copula'];c=diagnosis['results']['column_shuffle']
position=lines.index('## 研究への示唆')
paragraph=['## AUCが0.5になった反復の追加診断','','相関0.9・平均の課題のseed37を同じ設定で再実行し、結果が一致することを確認した。コピュラ版のエンコーダ出力は、特徴ごとの標準偏差の平均が約6.3×10⁻⁸で、ほぼ一定だった。テスト200行の予測確率はすべて同じ値となり、AUCは0.5だった。同じ固定表現へロジスティック回帰を当ててもAUC0.5だった。対して列置換版はエンコーダ出力の標準偏差の平均が約0.137、AUC約0.950だった。','','この反復では前学習後の表現が分類に必要な情報を保持できていない。なぜほぼ一定になったかは追加検証が必要であり、コピュラが常に表現を崩すと結論はしない。結果を見た後の診断として明記し、この反復を集計から除外しなかった。詳細はseed37_diagnosis.jsonとdiagnose_seed37.pyを参照。','','## 今回の結果をどう読むか','','相関0.9・平均の課題では、元の平均絶対相関0.898に対し列置換後0.340、コピュラ置換後0.882。既知の分類境界の変更率も11.0%から5.3%へ下がった。一方、分類AUCは列置換0.962に対しコピュラ0.871で、低下した反復を含む。関係保持の改善と、学習の改善が別の問題であることが分かる。','','相関0.9・差の課題では、相関はコピュラで保たれたが境界変更率は列置換26.2%、コピュラ25.6%で近かった。分類に必要なのが共通の傾向ではなく小さな差の場合、全体の相関を保つだけでは分類の意味を保てるとは限らない。両VIMEの分類AUCは約0.5、ラベルありだけの線形診断は約0.963だった。今回の学習設定でうまく学べていないことも考慮する必要がある。','','今回、コピュラ版の分類性能の優位性は確認できなかった。相関0.9・平均の課題では差の探索的95%区間が負側にあり、残る3条件では0を含んだ。強相関の平均低下にはseed37の表現がほぼ一定になった反復が大きく影響する。少数反復・複数条件の探索結果であるため、コピュラが一般に劣るとも、他条件で差が厳密に0であるとも結論しない。','']
lines[position:position]=paragraph
(ROOT/'実験レポート.md').write_text('\n'.join(lines))
print('Report saved.')
